            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "He who is in love is wise and is becoming wiser, sees newly every time he looks at the object beloved, drawing from it with his eyes and his mind those virtues which it possesses.", Author = "Ralph Waldo Emerson" },
