            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Slowly, slowly the Avenger comes, but comes surely.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Only the great generalizations survive.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Poetry teaches the enormous force of a few words, and, in proportion to the inspiration, checks loquacity.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "There are two classes of poets — the poets by education and practice, these we respect; and poets by nature, these we love.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "What is a weed? A plant whose virtues have not yet been discovered.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "We are never without a pilot. When we know not how to steer, and dare not hoist a sail, we can drift. The current knows the way, though we do not. The ship of heaven guides itself, and will not accept a wooden rudder.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "To different minds, the same world is a hell, and a heaven.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "A man contains all that is needful to his government within himself. He is made a law unto himself.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The purpose of life seems to be to acquaint a man with himself. He is not to live the future as described to him but to live the real future to the real present. The highest revelation is that God is in every man.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Everything intercepts us from ourselves.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "No man can have society upon his own terms. If he seeks it, he must serve it too.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "We are always getting ready to live, but never living.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Sometimes a scream is better than a thesis.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Let me never fall into the vulgar mistake of dreaming that I am persecuted whenever I am contradicted.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I wish to write such rhymes as shall not suggest a restraint, but contrariwise the wildest freedom.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Children are all foreigners.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Man exists for his own sake and not to add a laborer to the state.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "He needs no library, for he has not done thinking; no church, for he is himself a prophet; no statute book, for he hath the Lawgiver; no money, for he is value itself; no road, for he is at home where he is.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The best effect of fine persons is felt after we have left their presence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "How we hate this solemn Ego that accompanies the learned, like a double, wherever he goes.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "A good indignation brings out all one's powers.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "People say law but they mean wealth.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "People do not deserve to have good writing, they are so pleased with bad.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "You shall have joy, or you shall have power, said God; you shall not have both.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Do not be too timid and squeamish about your actions. All life is an experiment. The more experiments you make the better.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The sky is the daily bread of the eyes.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Poetry must be new as foam, and as old as the rock.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "It is easy to live for others; everybody does. I call on you to live for yourselves.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I hate quotation. Tell me what you know.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Blessed are those who have no talent!", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The blazing evidence of immortality is our dissatisfaction with any other solution.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "All the thoughts of a turtle are turtle.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The book written against fame and learning has the author's name on the title-page.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I have been writing & speaking what were once called novelties, for twenty five or thirty years, & have not now one disciple. Why? Not that what I said was not true; not that it has not found intelligent receivers but because it did not go from any wish in me to bring men to me, but to themselves. I delight in driving them from me. What could I do, if they came to me? — they would interrupt and encumber me. This is my boast that I have no school & no follower. I should account it a measure of the impurity of insight, if it did not create independence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The believing we do something when we do nothing is the first illusion of tobacco.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "A nation never falls but by suicide.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "You can take better care of your secret than another can.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Our age is retrospective. It builds the sepulchres of the fathers. It writes biographies, histories, and criticism. The foregoing generation beheld God and nature face to face; we, through their eyes. Why should not we also enjoy an original relation to the universe. Why should not we have a poetry and philosophy of insight and not of tradition, and a religion by revelation to us, and not the history of theirs?", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "If the stars should appear one night in a thousand years, how would men believe and adore, and preserve for many generations the remembrance of the city of God which had been shown!", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The stars awaken a certain reverence, because though always present, they are inaccessible; but all natural objects make a kindred impression, when the mind is open to their influence. Nature never wears a mean appearance.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "There is a property in the horizon which no man has but he whose eye can integrate all the parts, that is, the poet.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "To speak truly, few adult persons can see nature. Most persons do not see the sun. At least they have a very superficial seeing.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The lover of nature is he whose inward and outward senses are still truly adjusted to each other; who has retained the spirit of infancy even into the era of manhood. His intercourse with heaven and earth, becomes part of his daily food.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Standing on the bare ground, — my head bathed by the blithe air, and uplifted into infinite space, — all mean egotism vanishes. I become a transparent eye-ball; I am nothing; I see all; the currents of the Universal Being circulate through me; I am part or particle of God.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Beauty is the mark God sets upon virtue.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Give me health and a day, and I will make the pomp of emperors ridiculous.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Every natural fact is a symbol of some spiritual fact.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "A man is a god in ruins.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The state of society is one in which the members have suffered amputation from the trunk, and strut about so many walking monsters,—a good finger, a neck, a stomach, an elbow, but never a man.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The soul is subject to dollars.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I had better never see a book than to be warped by its attraction clean out of my own orbit, and made a satellite instead of a system. The one thing in the world, of value, is the active soul.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The soul active sees absolute truth; and utters truth, or creates.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "But genius looks forward: the eyes of men are set in his forehead, not in his hindhead: man hopes: genius creates.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Genius is always sufficiently the enemy of genius by over influence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Man Thinking must not be subdued by his instruments.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Character is higher than intellect...A great soul will be strong to live, as well as strong to think.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Of course, he who has put forth his total strength in fit actions, has the richest return of wisdom.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Life is our dictionary.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Success treads on every right step. For the instinct is sure, that prompts him to tell his brother what he thinks. He then learns, that in going down into the secrets of his own mind, he has descended into the secrets of all minds. He learns that he who has mastered any law in his private thoughts, is master to that extent of all men whose language he speaks, and of all into whose language his own can be translated.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Wherever Macdonald sits, there is the head of the table.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Do not yet see, that, if the single man plant himself indomitably on his instincts, and there abide, the huge world will come round to him.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "We will walk on our own feet; we will work with our own hands; we will speak our own minds...A nation of men will for the first time exist, because each believes himself inspired by the Divine Soul which also inspires all men.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The world is nothing, the man is all; in yourself is the law of all nature, and you know not yet how a globule of sap ascends; in yourself slumbers the whole of Reason; it is for you to know all, it is for you to dare all.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The man who renounces himself, comes to himself.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The sublime is excited in me by the great stoical doctrine, Obey thyself.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Wherever a man comes, there comes revolution. The old is for slaves.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "None believeth in the soul of man, but only in some man or person old and departed.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The imitator dooms himself to hopeless mediocrity.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "You will hear every day the maxims of a low prudence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "When you shall say, \"As others do, so will I. I renounce, I am sorry for it, my early visions; I must eat the good of the land, and let learning and romantic expectations go, until a more convenient season.\" — then dies the man in you; then once more perish the buds of art, and poetry, and science, as they have died already in a thousand thousand men.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Explore, and explore, and explore. Be neither chided nor flattered out of your position of perpetual inquiry. Neither dogmatise yourself, nor accept another's dogmatism.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Truth also has its roof, and bed, and board.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Thought is all light, and publishes itself to the universe. It will speak, though you were dumb, by its own miraculous organ.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The two parties which divide the state, the party of Conservatism and that of Innovation, are very old, and have disputed the possession of the world ever since it was made.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "It will never make any difference to a hero what the laws are. His greatness will shine and accomplish itself unto the end, whether they second him or not.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "All the meanness of my progenitors shall not bereave me of the power to make this hour and company fair and fortunate. Whatsoever streams of power and commodity flow to me, shall of me acquire healing virtue, and become fountains of safety.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Whosoever hereafter shall name my name, shall not record a malefactor, but a benefactor in the earth.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I cannot thank your law for my protection. I protect it. It is not in its power to protect me.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "There is always a certain meanness in the argument of conservatism, joined with a certain superiority in its fact.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Innovation is the salient energy; Conservatism the pause on the last movement.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "There is no king nor sovereign state That can fix a hero's rate.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Yet shine forever virgin minds, Loved by stars and the purest winds, Which, o'er passion throned sedate, Have not hazarded their state;", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "It is there for benefit; It is there for purging light; There for purifying storms; And its depths reflect all forms;", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Good bye, proud world! I'm going home; Thou art not my friend; I am not thine.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "For what are they all in their high conceit, When man in the bush with God may meet?", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Nor knowest thou what argument Thy life to thy neighbor's creed has lent: All are needed by each one, Nothing is fair or good alone.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Life is too short to waste The critic bite or cynic bark, Quarrel, or reprimand; 'Twill soon be dark; Up! mind thine own aim, and God speed the mark!", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "But all sorts of things and weather Must be taken in together To make up a year, And a sphere.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Talents differ; all is well and wisely put; If I cannot carry forests on my back, Neither can you crack a nut.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Tell them, dear, that, if eyes were made for seeing, Then beauty is its own excuse for Being.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Go where he will, the wise man is at home, His hearth the earth, his hall the azure dome.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Things are in the saddle, And ride mankind.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "There are two laws discrete Not reconciled, Law for man, and law for thing.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Olympian bards who sung Divine ideas below, Which always find us young And always keep us so.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Give all to love; Obey thy heart; Friends, kindred, days, Estate, good fame, Plans, credit, and the muse; Nothing refuse.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Heartily know, When half-gods go, The gods arrive.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Love not the flower they pluck, and know it not, And all their botany is Latin names.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The silent organ loudest chants The master's requiem.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "By the rude bridge that arched the flood, Their flag to April's breeze unfurled, Here once the embattled farmers stood, And fired the shot heard round the world.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Hast thou named all the birds without a gun; Loved the wood-rose, and left it on its stalk.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Earth laughs in flowers to see her boastful boys Earth-proud, proud of the earth which is not theirs; Who steer the plough, but can not steer their feet Clear of the grave.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Pass in, pass in, the angels say, In to the upper doors; Nor count compartments of the floors, But mount to Paradise By the stairway of surprise.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Thou animated torrid-zone.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Seeing only what is fair, Sipping only what is sweet, Thou dost mock at fate and care.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I like a church, I like a cowl, I love a prophet of the soul, And on my heart monastic aisles Fall like sweet strains or pensive smiles; Yet not for all his faith can see, Would I that cowled churchman be.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Not from a vain or shallow thought His awful Jove young Phidias brought.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Out from the heart of Nature rolled The burdens of the Bible old.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The hand that rounded Peter's dome, And groined the aisles of Christian Rome, Wrought in a sad sincerity, Himself from God he could not free; He builded better than he knew, The conscious stone to beauty grew.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Earth proudly wears the Parthenon As the best gem upon her zone.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The world is upheld by the veracity of good men: they make the earth wholesome.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "He is great who is what he is from Nature, and who never reminds us of others.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "When nature removes a great man, people explore the horizon for a successor; but none comes, and none will. His class is extinguished with him. In some other and quite different field the next man will appear.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Every hero becomes a bore at last.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "It costs a beautiful person no exertion to paint her image on our eyes; yet how splendid is that benefit! It costs no more for a wise soul to convey his quality to other men.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Great geniuses have the shortest biographies.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Things added to things, as statistics, civil history, are inventories. Things used as language are inexhaustibly attractive.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Keep cool: it will be all one a hundred years hence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Is not marriage an open question, when it is alleged, from the beginning of the world, that such as are in the institution wish to get out, and such as are out wish to get in?", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Thought is the property of him who can entertain it, and of him who can adequately place it.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The thing done avails, and not what is said about it. An original sentence, a step forward, is worth more than all the censures.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Classics which at home are drowsily read have a strange charm in a country inn, or in the transom of a merchant brig.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "The hearing ear is always found close to the speaking tongue.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Solvency is maintained by means of the national debt, on the principle, \"If you will not lend me the money, how can I pay you?\"", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "I find the Englishman to be him of all men who stands firmest in his shoes. They have in themselves what they value in their horses, — mettle and bottom.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "A creative economy is the fuel of magnificence.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "You have just dined, and however scrupulously the slaughterhouse is concealed in the graceful distance of miles, there is complicity.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Great men, great nations, have not been boasters and buffoons, but perceivers of the terror of life, and have manned themselves to face it.", Author = "Ralph Waldo Emerson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ralph_Waldo_Emerson", Text = "Men are what their mothers made them.", Author = "Ralph Waldo Emerson" },
